pub fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // Convert N to usize for indexing
    let n = N as usize;

    // First, set every element of `a` to 3
    for i in 0..n {
        a[i] = 3;
    }

    // Then, compute the total sum of the array
    let mut s: i32 = 0;
    for i in 0..n {
        s += a[i];
    }

    // Write the result into the single‐element `sum` buffer
    sum[0] = s;
}

